        out = {}
        for name in os.listdir(self.dir):
            p = os.path.join(self.dir, name)
            with open(p, "rb") as f:
                out[name] = (os.fstat(f.fileno()).st_mtime_ns, f.read())
        return out


class RangeTest(ScanBase):
    def test_full_scan_is_bytewise_ordered(self):
